{
  "name": "@dmmop/opencode-tps",
  "version": "1.0.2",
  "description": "OpenCode TUI plugin that displays response performance metrics.",
  "type": "module",
  "scripts": {
    "prepare": "husky"
  },
  "exports": {
    ".": "./src/index.ts",
    "./tui": "./tui.ts"
  },
  "files": [
    "src",
    "tui.ts",
    "README.md",
    "LICENSE"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/dmmop/opencode-tps.git"
  },
  "bugs": {
    "url": "https://github.com/dmmop/opencode-tps/issues"
  },
  "homepage": "https://github.com/dmmop/opencode-tps#readme",
  "license": "MIT",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "performance"
  ],
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opencode/plugin": "2.0.2"
  },
  "peerDependencies": {
    "@opentui/core": "0.5.10",
    "@opentui/solid": "0.5.10",
    "solid-js": "1.9.15"
  },
  "devDependencies": {
    "@commitlint/cli": "20.5.3",
    "@commitlint/config-conventional": "20.5.3",
    "@opentui/core": "0.5.10",
    "@opentui/solid": "0.5.10",
    "husky": "9.1.7",
    "solid-js": "1.9.15"
  }
}
